const ALLOWED_SENDERS = new Set(['osoulhospitality-wq']);
const TERMINAL_OR_BUSY = ['dragon-processing', 'dragon-completed', 'dragon-failed'];

const event = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const issue = event.issue ?? {};
const action = String(event.action ?? '').toLowerCase();
const sender = event.sender?.login ?? 'unknown';
const labels = Array.isArray(issue.labels)
  ? issue.labels.map((l) => (typeof l === 'string' ? l : l?.name)).filter(Boolean)
  : [];
const addedLabelName = event.label?.name ?? null;
const repository = event.repository?.full_name ?? `${event.repository?.owner?.login ?? 'unknown'}/${event.repository?.name ?? 'unknown'}`;
const issueNumber = issue.number ?? null;
const executionId = String($execution.id);
const receivedAt = new Date().toISOString();

function reject(reason, decision = 'ignored') {
  return { decision, reason, repository, issueNumber, action, sender, executionId, receivedAt };
}

if (!issueNumber) return [{ json: reject('no issue number in payload') }];

if (!ALLOWED_SENDERS.has(sender)) {
  return [{ json: reject(`sender '${sender}' is not in the authorized allowlist`, 'unauthorized') }];
}

const hasDragonTask = labels.includes('dragon-task');
const hasTerminalOrBusy = labels.some((l) => TERMINAL_OR_BUSY.includes(l));

let eligible = false;
let reason = '';

if (action === 'opened') {
  eligible = hasDragonTask && issue.state === 'open' && !hasTerminalOrBusy;
  reason = eligible ? 'opened with dragon-task already present' : 'opened without a clean dragon-task starting state';
} else if (action === 'labeled') {
  eligible = addedLabelName === 'dragon-task' && issue.state === 'open' && !hasTerminalOrBusy;
  reason = eligible
    ? 'dragon-task was the specific label just added'
    : `labeled event ignored (added label was '${addedLabelName}', not a fresh dragon-task application)`;
} else if (action === 'reopened') {
  eligible = hasDragonTask && issue.state === 'open' && !hasTerminalOrBusy;
  reason = eligible
    ? 'reopened with dragon-task present and no residual terminal/busy label (explicit retry state)'
    : 'reopened without a cleared terminal/busy label — not treated as an explicit retry';
} else {
  reason = `action '${action}' is not in the accepted set (opened, labeled, reopened)`;
}

if (!eligible) {
  return [{ json: reject(reason, 'ignored') }];
}

// commandVersion is GitHub's own issue.updated_at at the moment of this event.
// It is stable across duplicate/redelivered webhooks of the SAME transition
// (identical payload => identical updated_at) and changes on any later, genuinely
// new transition (a later explicit retry has a newer updated_at). This makes the
// idempotency key derivable without our own counter, so there is no separate
// race condition in computing it.
const commandVersion = issue.updated_at;
const idempotencyKey = `${repository}#${issueNumber}@${commandVersion}`;

return [{
  json: {
    decision: 'proceed',
    reason,
    repository,
    owner: event.repository?.owner?.login ?? 'osoulhospitality-wq',
    repositoryName: event.repository?.name ?? 'osoulhospitality-web',
    issueNumber,
    action,
    sender,
    title: issue.title ?? '',
    body: issue.body ?? '',
    author: issue.user?.login ?? 'unknown',
    commandVersion,
    idempotencyKey,
    executionId,
    receivedAt,
  },
}];

const item = { ...$json };
if (item.decision !== 'proceed') return [{ json: item }];

// GitHub can emit both opened and labeled for the same initial task. Treat both
// as one initial command. A deliberate close/reopen retry keeps its distinct
// GitHub updated_at value from Authorize & Classify.
item.commandVersion = ['opened', 'labeled'].includes(item.action)
  ? 'initial'
  : item.commandVersion;
item.idempotencyKey = `${item.repository}#${item.issueNumber}@${item.commandVersion}`;
return [{ json: item }];

