const source = $json ?? {};
function textFrom(value) {
  if (typeof value === 'string') return value.trim();
  if (Array.isArray(value)) return value.map(textFrom).filter(Boolean).join('\n\n').trim();
  if (!value || typeof value !== 'object') return '';
  for (const key of ['output', 'text', 'content', 'response', 'answer', 'message']) {
    const candidate = textFrom(value[key]);
    if (candidate) return candidate;
  }
  for (const key of ['messages', 'generations', 'data']) {
    const candidate = textFrom(value[key]);
    if (candidate) return candidate;
  }
  return '';
}
const delivery = textFrom(source).trim();
if (!delivery) {
  throw new Error(`EMPTY_DRAGON_DELIVERY: available keys: ${Object.keys(source).join(', ') || '(none)'}`);
}
return [{ json: { ...source, delivery, deliveryLength: delivery.length, normalizedAt: new Date().toISOString() } }];
